window.kbPageData["views/entry/k-bd26ee63feef5366"] = {"key":"entry/k-bd26ee63feef5366","state":{"route":"entry/k-bd26ee63feef5366"},"node":{"id":"k-bd26ee63feef5366","mode":"k","title":"特称命题不能推出对应的全称命题","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2024 C类 行测#94"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"公开回忆版的B项使用“所有”，设问使用“不能推出”，并标D为参考答案。仍需核对官方原卷的量词、设问和正式答案。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：“有的”无法推出“所有”","review":{"definition":"原题引文：“有的”无法推出“所有”","explanation":"有些跳远选手参加链球，而所有跳远选手都未参加跳高，所以至少有一名链球选手未参加跳高。另有一名运动员只参加链球和跳高，仍符合题干全部条件，却会使B项为假。因此B项不能推出。D项也不能推出，而且与800米跑选手均参加跳高、跳远选手均未参加跳高的条件矛盾。参考答案选D采取了优先选择必假项的口径，按题面“不能推出”的设问仍有两个选项。","references":[{"source":"web-452b1a57c66d8a4d","location":"来源标注为2024江苏A-101／江苏C-095的题目，B项及其解析","quote":"所有参加投掷链球的运动员都没有参加跳高"}],"evidence":"“有的”无法推出“所有”","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#94":{"paper":"江苏 2024 C类 行测","n":94,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",19],"asrc":["02d6b49839583bdaf297.pdf",28],"card":"87a3ccdce4441e2f0d446a9b","links":[{"id":"k-bd26ee63feef5366","role":"直接考查","why":"部分链球选手的参赛情况不足以确定全部链球选手的参赛情况。"}]}},"terms":{},"references":{"web-452b1a57c66d8a4d":{"name":"星光公考题库《2024江苏行测》田径运动会题（公开回忆版）","url":"https://www.xingguanggongkao.com/XingQuestion/search/subject_id/2.html?keywords=%E7%BA%BF%E4%B8%8A%E4%B8%87%E7%B1%B3%E8%B7%91"}},"topics":[],"units":{"k-bd26ee63feef5366":[["江苏 2024 C类 行测#94"]]}};
